#!/usr/bin/env bash
# Regenerate <adr-dir>/README.md: a list of every Accepted ADR, built from frontmatter.
# Usage: build-index.sh [adr-dir]   (default: docs/adrs)
set -euo pipefail

dir=${1:-docs/adrs}
[[ -d $dir ]] || { echo "build-index.sh: no such directory: $dir" >&2; exit 1; }

shopt -s nullglob
files=("$dir"/[0-9][0-9][0-9][0-9]-*.md)

out=$dir/README.md
tmp=$(mktemp "$dir/.README.md.XXXXXX")
trap 'rm -f "$tmp"' EXIT

{
	cat <<-'EOF'
	<!-- Generated by build-index.sh from ADR frontmatter. Do not edit by hand. -->

	# Architecture Decision Records

	Accepted decisions in force. Superseded and Deprecated ADRs remain in this directory as history.

	An Accepted ADR is never edited to change its decision; a changed decision is a new ADR that supersedes it. Use the `create-adr` skill for any ADR edit. After a change to any ADR's title or status, regenerate this file with the skill's `build-index.sh`.

	EOF

	# awk with no file operands would read stdin, so skip it when there are no ADRs.
	if ((${#files[@]})); then
		awk '
			function val(line) {
				sub(/^[^:]*:[ \t]*/, "", line)
				# Quoted: the value is the text inside the quotes (it may hold " #"); anything after is a comment.
				# No apostrophes in this awk program: it sits inside a single-quoted shell string.
				if (match(line, /^"[^"]*"/) || match(line, /^\x27[^\x27]*\x27/))
					return substr(line, 2, RLENGTH - 2)
				sub(/[ \t]+#.*$/, "", line)
				sub(/[ \t]+$/, "", line)
				return line
			}
			{ sub(/\r$/, "") }
			FNR == 1 { infm = ($0 == "---"); adr = title = status = ""; next }
			!infm { next }
			$0 == "---" {
				infm = 0
				if (status == "Accepted") {
					n = split(FILENAME, parts, "/")
					printf "- [ADR %s: %s](%s)\n", adr, title, parts[n]
					count++
				}
				next
			}
			/^adr:/    { adr = val($0) }
			/^title:/  { title = val($0) }
			/^status:/ { status = val($0) }
			END { if (!count) print "_No accepted ADRs yet._" }
		' "${files[@]}"
	else
		echo "_No accepted ADRs yet._"
	fi
} >"$tmp"

# mktemp creates 0600; the index is an ordinary tracked doc.
chmod 644 "$tmp"
mv "$tmp" "$out"
trap - EXIT
